import { get, put, del, BlobAccessError, BlobError, BlobStoreNotFoundError, BlobStoreSuspendedError, BlobServiceRateLimited, BlobRequestAbortedError } from '@vercel/blob';
import { MAX_PRIVATE_OBJECT_PART_BYTES } from '../ports/object-store.js';
import { createOperationalLogger, type OperationalLogger, type ProviderOperation, type ProviderFailureReason } from './operational-log.js';

/** Internal provider boundary. Keys are generated by ObjectLedger and never enter public DTOs. */
export interface PrivateObjectTransport {
  put(privateKey: string, bytes: Uint8Array, signal?: AbortSignal): Promise<void>;
  get(privateKey: string, signal?: AbortSignal): Promise<Uint8Array | null>;
  remove(privateKey: string, signal?: AbortSignal): Promise<void>;
  /** A resolved call confirms every key absent; a rejected call may have deleted any subset. */
  removeMany(privateKeys: readonly string[], signal?: AbortSignal): Promise<void>;
}
interface BlobSdk { readonly put: typeof put; readonly get: typeof get; readonly del: typeof del }
const keyPattern = /^ce\/v1\/[a-f0-9-]{36}\/[a-f0-9-]{36}\/[a-f0-9-]{36}$/;
function key(value: string): void { if (!keyPattern.test(value)) throw new TypeError('Invalid private object key.'); }

/** No implicit SDK retries: each provider attempt must be reserved by the persistent ledger. */
export class BlobObjectTransport implements PrivateObjectTransport {
  constructor(private readonly token: string, private readonly sdk: BlobSdk = { get, put, del }, private readonly log: OperationalLogger = createOperationalLogger()) {
    if (!token || /[\r\n\0]/.test(token)) throw new TypeError('Missing private object credentials.');
    if (process.env['VERCEL_BLOB_RETRIES'] !== undefined && process.env['VERCEL_BLOB_RETRIES'] !== '0') throw new TypeError('VERCEL_BLOB_RETRIES must be 0; application retries are metered.');
    process.env['VERCEL_BLOB_RETRIES'] = '0';
  }
  async put(privateKey: string, bytes: Uint8Array, signal?: AbortSignal): Promise<void> {
    key(privateKey); if (!bytes.byteLength || bytes.byteLength > MAX_PRIVATE_OBJECT_PART_BYTES) throw new RangeError('Private object part exceeds its byte budget.');
    try { await this.sdk.put(privateKey, Buffer.from(bytes), { access: 'private', token: this.token, addRandomSuffix: false, allowOverwrite: false, contentType: 'application/octet-stream', ...(signal ? { abortSignal: signal } : {}) }); }
    catch (error) { this.failed('blob-put', error); throw error; }
  }
  async get(privateKey: string, signal?: AbortSignal): Promise<Uint8Array | null> {
    key(privateKey); let result: Awaited<ReturnType<BlobSdk['get']>>;
    try { result = await this.sdk.get(privateKey, { access: 'private', token: this.token, useCache: false, ...(signal ? { abortSignal: signal } : {}) }); }
    catch (error) { this.failed('blob-get', error); throw error; }
    if (!result) return null;
    if (result.statusCode !== 200 || !result.stream || result.blob.size < 1 || result.blob.size > MAX_PRIVATE_OBJECT_PART_BYTES) {
      const error = new RangeError('Invalid private object length.');
      this.failed('blob-read', error, result.blob.size === 0 && result.headers?.get('content-length') === null ? 'missing-length' : 'invalid-length');
      throw error;
    }
    const reader = result.stream.getReader(), chunks: Uint8Array[] = []; let size = 0;
    let readReason: ProviderFailureReason | undefined;
    try {
      for (;;) { const read = await reader.read(); if (read.done) break; size += read.value.byteLength;
        if (size > MAX_PRIVATE_OBJECT_PART_BYTES || size > result.blob.size || signal?.aborted) { readReason = signal?.aborted ? 'timeout' : 'read-limit'; throw new Error('Private object transfer interrupted.'); } chunks.push(read.value);
      }
      if (size !== result.blob.size) { readReason = 'incomplete-read'; throw new Error('Incomplete private object transfer.'); } return Buffer.concat(chunks, size);
    } catch (error) { this.failed('blob-read', error, readReason); throw error;
    } finally { await reader.cancel().catch(() => undefined); reader.releaseLock(); }
  }
  async remove(privateKey: string, signal?: AbortSignal): Promise<void> {
    key(privateKey); try { await this.sdk.del(privateKey, { token: this.token, ...(signal ? { abortSignal: signal } : {}) }); }
    catch (error) { this.failed('blob-delete', error); throw error; }
  }
  async removeMany(privateKeys: readonly string[], signal?: AbortSignal): Promise<void> {
    if (!privateKeys.length || privateKeys.length > 100 || new Set(privateKeys).size !== privateKeys.length) throw new TypeError('Private deletion batch must contain 1–100 unique keys.');
    for (const value of privateKeys) key(value); signal?.throwIfAborted();
    try { await this.sdk.del([...privateKeys], { token: this.token, ...(signal ? { abortSignal: signal } : {}) }); }
    catch (error) { this.failed('blob-delete', error); throw error; }
  }
  private failed(providerOperation: ProviderOperation, error: unknown, reason?: ProviderFailureReason): void {
    const providerReason: ProviderFailureReason = reason ?? (error instanceof BlobAccessError ? 'access'
      : error instanceof BlobStoreNotFoundError ? 'store-missing' : error instanceof BlobStoreSuspendedError ? 'store-suspended'
      : error instanceof BlobServiceRateLimited ? 'rate-limit' : error instanceof BlobRequestAbortedError ? 'timeout'
      : error instanceof Error && ['AbortError', 'TimeoutError'].includes(error.name) ? 'timeout' : error instanceof BlobError ? 'provider-error' : 'other');
    try { this.log('provider_failed', { providerOperation, providerReason }); } catch { /* Diagnostics cannot change provider outcomes. */ }
  }
}
